1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import {AIError} from '../../types/ai.js';
12	import type {MessageChunk} from '../../types/ai.js';
13	import type {SessionStore} from '../../types/sessionStore.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
48	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
49	  };
50	}
51	
52	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
53	async function answerInTurn(
54	  ws: WebSocket,
55	  session: ChatSession,
56	  orchestrator: ChatOrchestrator,
57	  validation: ValidationResult,
58	  signal: AbortSignal | undefined
59	): Promise<void> {
60	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
61	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
62	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
63	    return;
64	  }
65	  const startedAt = Date.now();
66	  try {
67	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
68	  } finally {
69	    endTurn(ws, session, signal, startedAt);
70	  }
71	}
72	
73	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
74	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
75	  if (signal?.aborted) {
76	    log.info('message', 'turn abandoned: its socket closed', {
77	      sessionId: session.sessionId,
78	      elapsedMs: Date.now() - startedAt,
79	    });
80	    return;
81	  }
82	  sendStreamEnd(ws);
83	}
84	
85	async function answerUserMessage(
86	  ws: WebSocket,
87	  session: ChatSession,
88	  orchestrator: ChatOrchestrator,
89	  validation: ValidationResult,
90	  signal: AbortSignal | undefined
91	): Promise<void> {
92	  const message = validation.valid ? validation.data : undefined;
93	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
94	  await answerFrame(ws, session, validation);
95	}
96	
97	async function answerFrame(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  validation: ValidationResult,
101	  sessionStore?: SessionStore
102	): Promise<void> {
103	  if (!validation.valid) {
104	    log.warn('message', 'validation failed', {error: validation.error});
105	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
106	    return;
107	  }
108	
109	  const message = validation.data;
110	  if (message.type === 'ping') {
111	    handlePing(ws, message.timestamp);
112	    return;
113	  }
114	  if (message.type === 'list_sessions') {
115	    await handleListSessions(ws, session, message, sessionStore);
116	  }
117	}
118	
119	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
120	function isUserMessageFrame(rawMessage: unknown): boolean {
121	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
122	}
123	
124	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
125	  try {
126	    await action();
127	  } catch (error) {
128	    const message = error instanceof Error ? error.message : 'Unknown error';
129	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
130	    log.error('message', 'handling error', {error: message, code});
131	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
132	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
133	      return;
134	    }
135	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
136	  }
137	}
138	
139	async function handleUserMessage(
140	  ws: WebSocket,
141	  session: ChatSession,
142	  orchestrator: ChatOrchestrator,
143	  content: string,
144	  signal: AbortSignal | undefined
145	): Promise<void> {
146	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
147	
148	  const userEntry = createUserEntry(content);
149	  const userIndex = appendEntry(session, userEntry);
150	  sendUpsert(ws, userIndex, userEntry);
151	
152	  const parser = new ThinkingTagParser();
153	  const state: StreamState = {
154	    thinkingIndex: null,
155	    assistantIndex: null,
156	    suppressOutput: false,
157	    sentAssistantIndices: [],
158	  };
159	
160	  let textChunkCount = 0;
161	
162	  try {
163	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
164	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
165	      if (signal?.aborted) break;
166	      textChunkCount = logChunk(chunk, textChunkCount);
167	      processChunk(ws, session, state, parser, chunk);
168	    }
169	  } finally {
170	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
171	    flushHeldText(ws, session, state, parser);
172	    closeCutOff(ws, session, state, 'thinkingIndex');
173	    closeCutOff(ws, session, state, 'assistantIndex');
174	  }
175	
176	  if (textChunkCount > 0) {
177	    log.debug('stream', `received ${textChunkCount} text chunks`);
178	  }
179	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
180	}
181	
182	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
183	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
184	  if (chunk.type === 'text') return textChunkCount + 1;
185	
186	  if (textChunkCount > 0) {
187	    log.debug('stream', `received ${textChunkCount} text chunks`);
188	  }
189	
190	  if (chunk.type === 'tool_result') {
191	    log.debug('stream', 'tool_result chunk', {
192	      messageCount: chunk.clientMessages.length,
193	      types: chunk.clientMessages.map(m => m.type),
194	    });
195	    return 0;
196	  }
197	
198	  log.debug('stream', 'chunk', {type: chunk.type});
199	  return 0;
200	}
201	
202	function processChunk(
203	  ws: WebSocket,
204	  session: ChatSession,
205	  state: StreamState,
206	  parser: ThinkingTagParser,
207	  chunk: MessageChunk
208	): void {
209	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
210	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
211	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
212	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
213	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
214	}
215	
216	function processTextChunk(
217	  ws: WebSocket,
218	  session: ChatSession,
219	  state: StreamState,
220	  parser: ThinkingTagParser,
221	  text: string
222	): void {
223	  const segments = parser.push(text);
224	  for (const segment of segments) {
225	    handleTextSegment(ws, session, state, segment);
226	  }
227	}
228	
229	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
230	  if (segment.type === 'thinking') {
231	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
232	    return;
233	  }
234	  commitAndClear(ws, session, state, 'thinkingIndex');
235	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
236	}
237	
238	function streamSegment(
239	  ws: WebSocket,
240	  session: ChatSession,
241	  state: StreamState,
242	  key: StateIndexKey,
243	  createEntry: EntryFactory,
244	  content: string
245	): void {
246	  const isNew = initSegment(session, state, key, createEntry);
247	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
248	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
249	  appendDelta(session, state[key]!, content);
250	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
251	}
252	
253	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
254	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
255	  markSuppressed(session, index);
256	  sendSkip(ws, index);
257	}
258	
259	function markSuppressed(session: ChatSession, index: number): void {
260	  const entry = session.entries[index];
261	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
262	}
263	
264	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
265	  if (state[key] !== null) return false;
266	  state[key] = appendEntry(session, createEntry());
267	  return true;
268	}
269	
270	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
271	  const index = state[key];
272	  if (index === null) return;
273	
274	  commitEntry(session, index);
275	  state[key] = null;
276	
277	  // Only what the client received can be retracted, and only assistant entries.
278	  if (state.suppressOutput) return;
279	
280	  sendCommit(ws, index);
281	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
282	}
283	
284	function processToolUseChunk(
285	  ws: WebSocket,
286	  session: ChatSession,
287	  toolCall: {name: string; input: Record<string, unknown>}
288	): void {
289	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
290	  const toolIndex = appendEntry(session, toolEntry);
291	  sendUpsert(ws, toolIndex, toolEntry);
292	}
293	
294	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
295	  for (const msg of clientMessages) {
296	    log.debug('stream', 'forwarding client message to frontend', {
297	      type: msg.type,
298	      index: 'index' in msg ? msg.index : undefined,
299	    });
300	    sendJson(ws, msg);
301	  }
302	}
303	
304	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
305	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
306	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
307	  commitOpenEntries(ws, session, state);
308	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
309	
310	  for (const idx of state.sentAssistantIndices) {
311	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
312	    markSuppressed(session, idx);
313	  }
314	
315	  state.sentAssistantIndices = [];
316	  state.suppressOutput = true;
317	}
318	
319	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
320	  flushHeldText(ws, session, state, parser);
321	  commitOpenEntries(ws, session, state);
322	}
323	
324	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
325	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
326	  for (const segment of parser.flush()) {
327	    handleTextSegment(ws, session, state, segment);
328	  }
329	}
330	
331	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
332	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
333	  const index = state[key];
334	  if (index === null) return;
335	  markTruncated(session, index);
336	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
337	  commitAndClear(ws, session, state, key);
338	}
339	
340	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
341	  commitAndClear(ws, session, state, 'thinkingIndex');
342	  commitAndClear(ws, session, state, 'assistantIndex');
343	}
344	
345	async function handleListSessions(
346	  ws: WebSocket,
347	  session: ChatSession,
348	  message: ListSessionsMessage,
349	  sessionStore?: SessionStore
350	): Promise<void> {
351	  if (typeof sessionStore?.listFor !== 'function') {
352	    sendJson(ws, {type: 'session_list', sessions: []});
353	    return;
354	  }
355	  try {
356	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
357	    const sessions = summaries.map(s => ({
358	      sessionId: s.sessionId,
359	      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : (s.createdAt as string),
360	      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : (s.updatedAt as string),
361	      entryCount: s.entryCount,
362	    }));
363	    sendJson(ws, {type: 'session_list', sessions});
364	  } catch (err) {
365	    const errorMessage = err instanceof Error ? err.message : 'Unknown error';
366	    log.error('ws', 'listFor failed', {userId: session.userId, error: errorMessage});
367	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
368	  }
369	}
370	
371	function handlePing(ws: WebSocket, timestamp: number): void {
372	  ws.send(JSON.stringify({type: 'pong', timestamp}));
373	}
