describe('list_sessions dispatch', () => {
  it('calls listFor with session.userId and answers session_list with ISO-serialised dates', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const summary: SessionSummary = {
      sessionId: 's2',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-01T01:00:00.000Z'),
      entryCount: 2,
    };
    const listFor = jest.fn().mockResolvedValue([summary]);
    const store = {listFor} as unknown as SessionStore;
    const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;

    const handle = createMessageHandler(orchestrator, store);
    await handle(ws, session, {type: 'list_sessions', limit: 5});

    expect({called: listFor.mock.calls[0], frames: sent}).toEqual({
      called: ['u1', {limit: 5, before: undefined}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
