import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type Validator = (message: Record<string, unknown>) => ValidationResult;

type CursorResult = {valid: true; cursor: SessionCursor} | {valid: false; error: string};

const validators: Record<string, Validator> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators[message.type];
  if (!validate) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validate(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function isValidLimit(limit: unknown): boolean {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function validateBeforeCursor(before: unknown): CursorResult {
  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }
  const cursor = before as Record<string, unknown>;
  const {sessionId, updatedAt} = cursor;

  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return {
      valid: false,
      error: `list_sessions before.sessionId must be a string of 1–${MAX_SESSION_ID_LENGTH} characters`,
    };
  }

  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
  }

  if (!isFinite(Date.parse(String(updatedAt)))) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a parseable date'};
  }

  return {valid: true, cursor: {updatedAt, sessionId} as SessionCursor};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const frame: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined && !isValidLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (message.limit !== undefined) frame.limit = message.limit as number;

  if (message.before === undefined) return {valid: true, data: frame};

  const beforeResult = validateBeforeCursor(message.before);
  if (!beforeResult.valid) return {valid: false, error: beforeResult.error};
  frame.before = beforeResult.cursor;

  return {valid: true, data: frame};
}

